function makeLobbyState(players) {
  return {
    status: "lobby",
    players,
    pool: [],
    board: {},
    logs: [],
    winnerId: null,
    rounds: 0,
    goCallerId: null,
    lives: 3,
    ...initialBoardBounds
  };
}
function startGame(state) {
  let pool2 = buildShuffledPool();
  const players = state.players.map((p) => {
    const { drawn, remaining } = draw(pool2, 5);
    pool2 = remaining;
    return { ...p, hand: drawn, totalTilesDrawn: drawn.length, board: {}, ...initialBoardBounds };
  });
  return {
    ...state,
    status: "playing",
    pool: pool2,
    players,
    board: {},
    logs: [{ id: uuid5(), message: "Game started! Each player drew 5 tiles.", timestamp: now() }],
    rounds: 0,
    winnerId: null,
    goCallerId: null,
    lives: 3,
    ...initialBoardBounds
  };
}
